import { Link } from 'react-router-dom';

export default function AuthHeader({
  styles,
  primaryTo = '/register',
  primaryLabel = 'CREATE ACCOUNT',
  secondaryTo = '/login',
  secondaryLabel = 'LOG IN',
}) {
  return (
    <header className={styles.header}>
      <div className={styles.headerLeft}>
        <Link to="/finbric" className={styles.brand}>
          <span className={styles.brandMark}>F</span>
          <div>
            <p className={styles.brandName}>Finbric</p>
            <p className={styles.brandTagline}>Community finance platform</p>
          </div>
        </Link>
      </div>

      <div className={styles.headerActions}>
        <Link to={primaryTo} className={styles.createAccountButton || styles.signUpBtn}>
          {primaryLabel}
        </Link>
        <Link to={secondaryTo} className={styles.loginBtn}>
          {secondaryLabel}
        </Link>
      </div>
    </header>
  );
}
